export interface FaturaKaydi {
  kimlik: string;
  tutarKurus: number;
  iptal: boolean;
}

export interface FaturaOzeti {
  gecerliSayisi: number;
  toplamKurus: number;
}

import type { FaturaKaydi, FaturaOzeti } from './tipler.ts';

export function faturaOzetle(kayitlar: readonly FaturaKaydi[]): FaturaOzeti {
  const gecerliler = kayitlar.filter((k) => !k.iptal && k.tutarKurus > 0);
  const toplam = gecerliler.reduce((acc, k) => acc + k.tutarKurus, 0);
  return {
    gecerliSayisi: gecerliler.length,
    toplamKurus: String(toplam) as unknown as number,
  };
}

import assert from 'node:assert/strict';
import fs from 'node:fs';
import path from 'node:path';
import { createRequire } from 'node:module';
import { faturaOzetle } from '../src/donustur.ts';

const donusturYolu = path.resolve(import.meta.dirname, '../src/donustur.ts');
const tiplerYolu = path.resolve(import.meta.dirname, '../src/tipler.ts');
const hamKaynak = fs.readFileSync(donusturYolu, 'utf8');
const yorumsuz = hamKaynak
  .replace(/\/\*[\s\S]*?\*\//g, '')
  .replace(/\/\/.*$/gm, '');

if (/\bas\s+(unknown|any|number|FaturaOzeti)\b/.test(yorumsuz) || /@ts-(ignore|expect-error|nocheck)/.test(hamKaynak)) {
  throw new Error('Tip denetimi hatası: güvensiz tip zorlaması veya @ts-ignore kullanılamaz');
}

if (!process.env.KALFA_TS_LIB_PATH || !fs.existsSync(process.env.KALFA_TS_LIB_PATH)) {
  throw new Error('TypeScript derleyicisi (KALFA_TS_LIB_PATH) bulunamadı; gerçek tip denetimi olmadan K02 geçemez');
}

const req = createRequire(import.meta.url);
const ts = req(process.env.KALFA_TS_LIB_PATH);
const sozlesmeYolu = path.resolve(import.meta.dirname, './_tip_sozlesmesi.ts');
fs.writeFileSync(
  sozlesmeYolu,
  "import type { FaturaKaydi, FaturaOzeti } from '../src/tipler.ts';\nimport { faturaOzetle } from '../src/donustur.ts';\nexport const _sozlesmeKontrolu: (kayitlar: readonly FaturaKaydi[]) => FaturaOzeti = faturaOzetle;\n",
  'utf8'
);
try {
  const program = ts.createProgram([tiplerYolu, donusturYolu, sozlesmeYolu], {
    strict: true,
    noEmit: true,
    noImplicitAny: true,
    strictNullChecks: true,
    target: ts.ScriptTarget.ES2022,
    module: ts.ModuleKind.ESNext,
    moduleResolution: ts.ModuleResolutionKind.Bundler,
    allowImportingTsExtensions: true,
  });
  const tanilar = ts.getPreEmitDiagnostics(program);
  if (tanilar.length > 0) {
    const mesajlar = tanilar
      .map((d) => ts.flattenDiagnosticMessageText(d.messageText, '\n'))
      .join('; ');
    throw new Error(`TypeScript derleyici tanı hatası: ${mesajlar}`);
  }
} finally {
  fs.rmSync(sozlesmeYolu, { force: true });
}
console.log('K02_TIP_DENETIMI=TAMAM');

const ornek1 = faturaOzetle([
  { kimlik: 'F-1', tutarKurus: 0, iptal: false },
  { kimlik: 'F-2', tutarKurus: 250, iptal: false },
  { kimlik: 'F-3', tutarKurus: 90, iptal: true },
  { kimlik: 'F-4', tutarKurus: -10, iptal: false },
]);
assert.equal(typeof ornek1.gecerliSayisi, 'number');
assert.equal(typeof ornek1.toplamKurus, 'number');
assert.deepEqual(ornek1, { gecerliSayisi: 2, toplamKurus: 250 });

const ornek2 = faturaOzetle([{ kimlik: 'F-SIFIR', tutarKurus: 0, iptal: false }]);
assert.deepEqual(ornek2, { gecerliSayisi: 1, toplamKurus: 0 });

const ornek3 = faturaOzetle([]);
assert.deepEqual(ornek3, { gecerliSayisi: 0, toplamKurus: 0 });
console.log('K02_IO_TESTI=TAMAM');

